function Invoke-FrigateLoginWithCredential
{
    <#
    .SYNOPSIS
    Login with credentials

    .DESCRIPTION
    **Access:** Public — no authentication required.

    Authenticates a user with username and password. Returns a JWT token as a secure HTTP-only cookie that can be used for subsequent API requests. The JWT token can also be retrieved from the response and used as a Bearer token in the Authorization header.

    Example using Bearer token:
    ```
    curl -H "Authorization: Bearer <token_value>" https://frigate_ip:8971/api/profile
    ```

    Calls POST /login.

    .PARAMETER User
    User

    .PARAMETER Password
    Password
    A SecureString (see ConvertTo-SecureString); it is converted to text only to build the request.

    .PARAMETER InputObject
    A hashtable or object whose properties are sent as the request body. Keys may be this command's parameter names or the API's own property names.
    All piped input is received here, so one command can process many requests from the pipeline.
    Individually specified parameters override matching keys.

    .PARAMETER Endpoint
    Base URL of the API. Defaults to the saved/default endpoint (see the *DefaultEndpoint commands).

    .PARAMETER Credential
    Credential for the API; the password is used as the token/key when the API uses one.

    .PARAMETER Headers
    Extra request headers.

    .PARAMETER TimeoutSec
    Request timeout in seconds (default 100).

    .PARAMETER OutFile
    Save the response body to this file (or into this directory). Binary responses without -OutFile are saved to a temp file.

    .EXAMPLE
    Invoke-FrigateLoginWithCredential -User 'example' -Password (Read-Host -AsSecureString) -OutFile ./output.bin

    .OUTPUTS
    System.IO.FileInfo, pscustomobject, string

    .LINK
    POST /login
    #>
    [CmdletBinding()]
    [OutputType([System.IO.FileInfo], [pscustomobject], [string])]
    param(
        [Parameter(Mandatory, ParameterSetName = 'Properties')]
        [string]$User,

        [Parameter(Mandatory, ParameterSetName = 'Properties')]
        [securestring]$Password,

        [Parameter(Mandatory, ParameterSetName = 'InputObject', ValueFromPipeline)]
        [object]$InputObject,

        [Parameter()]
        [ValidatePattern('^https?://')]
        [string]$Endpoint,

        [Parameter()]
        [System.Management.Automation.Credential()]
        [pscredential]$Credential,

        [Parameter()]
        [hashtable]$Headers,

        [Parameter()]
        [ValidateRange(0, 86400)]
        [int]$TimeoutSec,

        [Parameter()]
        [string]$OutFile
    )

    process
    {
        if ($PSBoundParameters.ContainsKey('InputObject'))
        {
            $propertyMap = @{
                User     = 'user'
                Password = 'password'
            }
            $body = ConvertTo-OpenApiBodyTable -InputObject $InputObject -PropertyMap $propertyMap
        } else
        {
            $body = [ordered]@{}
        }
        if ($PSBoundParameters.ContainsKey('User')) { $body['user'] = $User }
        if ($PSBoundParameters.ContainsKey('Password')) { $body['password'] = [System.Net.NetworkCredential]::new('', $Password).Password }
        foreach ($required in @('user', 'password'))
        {
            if (-not $body.Contains($required))
            {
                throw "Invoke-FrigateLoginWithCredential: the request is missing required property '$required'."
            }
        }

        $request = @{
            ClientInfo   = $Script:FrigateClientInfo
            Method       = 'POST'
            PathTemplate = '/login'
            Body         = $body
        }
        foreach ($common in 'Endpoint', 'Credential', 'Headers', 'TimeoutSec', 'OutFile')
        {
            if ($PSBoundParameters.ContainsKey($common))
            {
                $request[$common] = $PSBoundParameters[$common]
            }
        }

        Invoke-OpenApiRequest @request
    }
}

