    Base URL of the API. Defaults to the saved/default endpoint (see the *DefaultEndpoint commands).

    .PARAMETER Credential
    Credential for the API; the password is used as the token/key when the API uses one.

    .PARAMETER Headers
    Extra request headers.

    .PARAMETER TimeoutSec
    Request timeout in seconds (default 100).

    .EXAMPLE
    Start-FrigateCustomRecordingExport -CameraName 'example' -StartTime 1.0 -EndTime 1.0

    .OUTPUTS
    Frigate.StartExportResponse

    .LINK
    POST /export/custom/{camera_name}/start/{start_time}/end/{end_time}
    #>
    [CmdletBinding()]
    [OutputType('Frigate.StartExportResponse')]
    param(
        [Parameter(Mandatory, ValueFromPipelineByPropertyName)]
        [Alias('camera_name')]
        [string]$CameraName,

        [Parameter(Mandatory, ValueFromPipelineByPropertyName)]
        [Alias('start_time')]
        [double]$StartTime,

        [Parameter(Mandatory, ValueFromPipelineByPropertyName)]
        [Alias('end_time', 'Id')]
        [double]$EndTime,

        [Parameter()]
        [ValidateSet('recordings', 'preview')]
        [string]$Source,

        [Parameter()]
        [ValidateLength(0, 256)]
        [string]$Name,

        [Parameter()]
        [Alias('image_path')]
        [string]$ImagePath,

        [Parameter()]
        [Alias('export_case_id')]
        [ValidateLength(0, 30)]
        [string]$ExportCaseId,

        [Parameter()]
        [Alias('ffmpeg_input_args')]
        [string]$FfmpegInputArgs,

        [Parameter()]
        [Alias('ffmpeg_output_args')]
        [string]$FfmpegOutputArgs,

        [Parameter()]
        [Alias('cpu_fallback')]
        [switch]$CpuFallback,

        [Parameter(ValueFromPipeline)]
        [object]$InputObject,

        [Parameter()]
        [ValidatePattern('^https?://')]
        [string]$Endpoint,

        [Parameter()]
        [System.Management.Automation.Credential()]
        [pscredential]$Credential,

        [Parameter()]
        [hashtable]$Headers,

        [Parameter()]
        [ValidateRange(0, 86400)]
        [int]$TimeoutSec
    )

    process
    {
        $pathParameter = @{}
        $pathParameter['camera_name'] = $CameraName
        $pathParameter['start_time'] = $StartTime
        $pathParameter['end_time'] = $EndTime

        if ($PSBoundParameters.ContainsKey('InputObject'))
