                ImagePath        = 'image_path'
                ExportCaseId     = 'export_case_id'
                FfmpegInputArgs  = 'ffmpeg_input_args'
                FfmpegOutputArgs = 'ffmpeg_output_args'
                CpuFallback      = 'cpu_fallback'
            }
            $body = ConvertTo-OpenApiBodyTable -InputObject $InputObject -PropertyMap $propertyMap
        } else
        {
            $body = [ordered]@{}
        }
        if ($PSBoundParameters.ContainsKey('Source')) { $body['source'] = $Source }
        if ($PSBoundParameters.ContainsKey('Name')) { $body['name'] = $Name }
        if ($PSBoundParameters.ContainsKey('ImagePath')) { $body['image_path'] = $ImagePath }
        if ($PSBoundParameters.ContainsKey('ExportCaseId')) { $body['export_case_id'] = $ExportCaseId }
        if ($PSBoundParameters.ContainsKey('FfmpegInputArgs')) { $body['ffmpeg_input_args'] = $FfmpegInputArgs }
        if ($PSBoundParameters.ContainsKey('FfmpegOutputArgs')) { $body['ffmpeg_output_args'] = $FfmpegOutputArgs }
        if ($PSBoundParameters.ContainsKey('CpuFallback')) { $body['cpu_fallback'] = [bool]$CpuFallback }

        $request = @{
            ClientInfo    = $Script:FrigateClientInfo
            Method        = 'POST'
            PathTemplate  = '/export/custom/{camera_name}/start/{start_time}/end/{end_time}'
            PathParameter = $pathParameter
            Body          = $body
            ResultType    = 'Frigate.StartExportResponse'
        }
        foreach ($common in 'Endpoint', 'Credential', 'Headers', 'TimeoutSec', 'OutFile')
        {
            if ($PSBoundParameters.ContainsKey($common))
            {
                $request[$common] = $PSBoundParameters[$common]
            }
        }

        Invoke-OpenApiRequest @request
    }
}

